import React from 'react';

export default function ServerTimestamp() {
  const timestamp = new Date().toISOString();

  return (
    <div className="p-4 border rounded-lg bg-gray-100 dark:bg-gray-800">
      <h2 className="text-xl font-bold mb-2">Server Timestamp</h2>
      <p suppressHydrationWarning>{timestamp}</p>
    </div>
  );
}

